    '_content' => '<!DOCTYPE html>
<html lang="ru" itemscope itemtype="https://schema.org/WebPage">

<head>
    {include \'meta\'}
    <title>{$_modx->resource.pagetitle} — Дом Оз</title>
    <meta name="description" content="{$_modx->resource.description}">
    {$_modx->resource.codecviz}

    <!-- Tailwind CSS (БЕЗ defer!) -->
    <script src="https://cdn.tailwindcss.com"></script>
    <script>
        tailwind.config = {
            theme: {
                extend: {
                    fontFamily: { sans: [\'Inter\', \'sans-serif\'] },
                    colors: {
                        primary: \'#558255\',
                        \'primary-dark\': \'#3d5c3d\',
                        accent: \'#d4a574\',
                        dark: \'#1a1a1a\'
                    }
                }
            }
        }
    </script>

    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&display=swap"
        rel="stylesheet">

    <style>
        body {
            font-family: \'Inter\', sans-serif;
            background: #fff;
            color: #1a1a1a;
        }

        .section-title {
            position: relative;
            display: inline-block;
        }

        .section-title::after {
            content: \'\';
            position: absolute;
            bottom: -8px;
            left: 50%;
            transform: translateX(-50%);
            width: 60px;
            height: 3px;
            background: linear-gradient(90deg, #558255, #d4a574);
            border-radius: 2px;
        }

        /* Price table */
        .price-table {
            border-collapse: separate;
            border-spacing: 0;
            width: 100%;
            background: #fff;
            border-radius: 16px;
            overflow: hidden;
            box-shadow: 0 4px 20px rgba(0, 0, 0, 0.06);
            border: 1px solid #e5e7eb;
        }

        .price-table thead {
            background: linear-gradient(135deg, #558255 0%, #3d5c3d 100%);
            color: #fff;
        }

        .price-table thead th {
            padding: 18px 24px;
            font-weight: 600;
            font-size: 14px;
            text-transform: uppercase;
            letter-spacing: 0.5px;
            text-align: left;
        }

        .price-table thead th:last-child {
            text-align: right;
        }

        .price-table thead th:nth-child(2) {
            text-align: center;
        }

        .price-table tbody tr {
            transition: all 0.25s ease;
            border-bottom: 1px solid #f1f5f1;
        }

        .price-table tbody tr:last-child {
            border-bottom: none;
        }

        .price-table tbody tr:hover {
            background: #f8faf8;
            transform: scale(1.005);
        }

        .price-table tbody td {
            padding: 18px 24px;
            font-size: 15px;
            color: #1a1a1a;
            vertical-align: middle;
        }

        .price-table tbody td:last-child {
            text-align: right;
            font-weight: 700;
            color: #558255;
            font-size: 16px;
            white-space: nowrap;
        }

        .price-table tbody td:nth-child(2) {
            text-align: center;
            color: #6b7280;
            font-size: 14px;
        }

        .price-table tbody td:first-child {
            font-weight: 500;
        }

        /* Section card */
        .price-section {
            transition: all 0.3s ease;
        }

        .price-section:hover {
            transform: translateY(-4px);
            box-shadow: 0 20px 40px rgba(85, 130, 85, 0.15);
        }

        .price-section-icon {
            transition: all 0.4s ease;
        }

        .price-section:hover .price-section-icon {
            transform: rotate(-8deg) scale(1.1);
            background: #558255;
            color: #fff;
        }

        /* FAQ accordion */
        .acor-container input[type="checkbox"] {
            display: none;
        }

        .acor-container .acor-body {
            max-height: 0;
            overflow: hidden;
            transition: all 0.3s ease;
        }

        .acor-container input[type="checkbox"]:checked+label+.acor-body {
            max-height: 400px;
            padding: 0 20px 20px;
        }

        .acor-container label {
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding: 18px 20px;
            background: #778A6E;
            border-radius: 10px;
            cursor: pointer;
            border: 1px solid #e5e7eb;
            font-weight: 500;
            color: #fff;
        }

        .acor-container label:hover {
            background: #3d5c3d;
            border-color: #558255;
        }

        .acor-container label::after {
            content: \'+\';
            font-size: 22px;
            color: #558255;
            width: 30px;
            height: 30px;
            display: flex;
            align-items: center;
            justify-content: center;
            background: #fff;
            border-radius: 50%;
            transition: all 0.3s;
            flex-shrink: 0;
        }

        .acor-container input[type="checkbox"]:checked+label::after {
            content: \'−\';
            background: #558255;
            color: #fff;
        }

        /* Feature card */
        .feature-card {
            transition: all 0.3s ease;
        }

        .feature-card:hover {
            transform: translateY(-6px);
            box-shadow: 0 20px 40px rgba(0, 0, 0, 0.1);
        }

        /* Sticky TOC */
        .toc-item {
            transition: all 0.2s ease;
        }

        .toc-item:hover {
            background: #f8faf8;
            color: #558255;
            padding-left: 24px;
        }

        /* Mobile table */
        @media (max-width: 640px) {
            .price-table thead {
                display: none;
            }

            .price-table tbody tr {
                display: block;
                padding: 16px;
                margin-bottom: 12px;
                border: 1px solid #e5e7eb;
                border-radius: 12px;
            }

            .price-table tbody td {
                display: flex;
                justify-content: space-between;
                padding: 8px 0;
                text-align: right;
                border: none;
            }

            .price-table tbody td::before {
                content: attr(data-label);
                font-weight: 600;
                color: #6b7280;
                text-align: left;
                font-size: 13px;
            }

            .price-table tbody td:last-child {
                font-size: 18px;
                color: #558255;
                border-top: 1px dashed #e5e7eb;
                padding-top: 12px;
                margin-top: 4px;
            }
        }
    </style>

    <!-- Breadcrumb Schema -->
