    font-size: 15px;
    color: #6b7280;
    line-height: 1.5;
}

.modal-form-body {
    display: flex;
    flex-direction: column;
    gap: 16px;
}

.modal-form-field {
    position: relative;
}

.modal-input {
    width: 100%;
    padding: 14px 18px;
    border: 2px solid #e5e7eb;
    border-radius: 12px;
    font-size: 15px;
    color: #1a1a1a;
    background: #fff;
    transition: all 0.2s ease;
